# NoorPro's own English, Urdu and Hindi renderings for the Darood section (1.2.0 (116)); Urdu for Quran 33:56 stays Kanz-ul-Iman (PD).
T = {
'sunnah/q3356': dict(
 en="Indeed Allah and His angels send blessings upon the Prophet. O you who believe, send blessings upon him and greet him with abundant peace.",
 hi="बेशक अल्लाह और उसके फ़रिश्ते नबी पर दुरूद भेजते हैं। ऐ ईमान वालो! तुम भी उन पर दुरूद भेजो और ख़ूब सलाम भेजो।"),
'sunnah/ibrahimi': dict(
 en="O Allah, send blessings upon Muhammad and upon the family of Muhammad, as You sent blessings upon Ibrahim and upon the family of Ibrahim; You are Praiseworthy, Glorious. O Allah, bless Muhammad and the family of Muhammad, as You blessed Ibrahim and the family of Ibrahim; You are Praiseworthy, Glorious.",
 ur="اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت نازل فرما، جیسے تو نے ابراہیم اور آلِ ابراہیم پر رحمت نازل فرمائی، بیشک تو تعریف والا، بزرگی والا ہے۔ اے اللہ! محمد ﷺ اور آلِ محمد پر برکت نازل فرما، جیسے تو نے ابراہیم اور آلِ ابراہیم پر برکت نازل فرمائی، بیشک تو تعریف والا، بزرگی والا ہے۔",
 hi="ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत नाज़िल कर, जैसे तूने इब्राहीम और आल-ए-इब्राहीम पर रहमत नाज़िल की, बेशक तू तारीफ़ वाला, बुज़ुर्गी वाला है। ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर बरकत नाज़िल कर, जैसे तूने इब्राहीम और आल-ए-इब्राहीम पर बरकत नाज़िल की, बेशक तू तारीफ़ वाला, बुज़ुर्गी वाला है।"),
'sunnah/short': dict(en="May Allah send blessings and peace upon him.", ur="اللہ ان پر رحمت اور سلامتی نازل فرمائے۔", hi="अल्लाह उन पर रहमत और सलामती नाज़िल करे।"),
'sunnah/m384': dict(
 tr="Idhā samiʿtumu l-mu'adhdhina fa-qūlū mithla mā yaqūl, thumma ṣallū ʿalayya, fa-innahū man ṣallā ʿalayya ṣalātan ṣalla Llāhu ʿalayhi bihā ʿashrā, thumma salu Llāha liya l-wasīlah…",
 en="'When you hear the mu'adhdhin, repeat what he says, then send blessings upon me, for whoever sends one blessing upon me, Allah sends ten upon him. Then ask Allah to grant me al-Wasilah, a rank in Paradise fitting only one servant of Allah, and I hope to be him; whoever asks for al-Wasilah for me, my intercession becomes due for him.'",
 ur="'جب تم مؤذن کو سنو تو وہی کہو جو وہ کہتا ہے، پھر مجھ پر درود بھیجو، کیونکہ جو مجھ پر ایک بار درود بھیجتا ہے اللہ اس پر دس رحمتیں بھیجتا ہے۔ پھر میرے لیے وسیلہ مانگو، جو جنت کا ایک درجہ ہے جو اللہ کے بندوں میں سے صرف ایک بندے کے لائق ہے، اور مجھے امید ہے کہ وہ میں ہوں گا؛ جو میرے لیے وسیلہ مانگے اس کے لیے میری شفاعت واجب ہو گئی۔'",
 hi="'जब तुम मुअज़्ज़िन को सुनो तो वही कहो जो वह कहता है, फिर मुझ पर दुरूद भेजो, क्योंकि जो मुझ पर एक बार दुरूद भेजता है अल्लाह उस पर दस रहमतें भेजता है। फिर मेरे लिए वसीला माँगो, जो जन्नत का एक दर्जा है जो अल्लाह के बंदों में से सिर्फ़ एक के लायक़ है, और मुझे उम्मीद है कि वह मैं हूँगा; जो मेरे लिए वसीला माँगे उसके लिए मेरी शफ़ाअत वाजिब हो गई।'"),
'sunnah/t484': dict(
 tr="Awla n-nāsi bī yawma l-qiyāmati aktharuhum ʿalayya ṣalāh.",
 en="'The people closest to me on the Day of Resurrection are those who sent the most blessings upon me.'",
 ur="'قیامت کے دن مجھ سے سب سے زیادہ قریب وہ ہوں گے جو مجھ پر سب سے زیادہ درود بھیجتے ہیں۔'",
 hi="'क़यामत के दिन मुझसे सबसे ज़्यादा क़रीब वे होंगे जो मुझ पर सबसे ज़्यादा दुरूद भेजते हैं।'"),
'classic/tunajjina': dict(
 en="O Allah, send blessings upon our master Muhammad — a blessing by which You save us from all terrors and afflictions, fulfil for us all our needs, purify us from all sins, raise us to the highest ranks with You, and bring us to the furthest goals of every good, in this life and after death.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر ایسی رحمت نازل فرما جس کے ذریعے تو ہمیں تمام خوف اور آفتوں سے نجات دے، ہماری تمام حاجتیں پوری فرمائے، ہمیں تمام گناہوں سے پاک کرے، اپنے ہاں ہمیں سب سے بلند درجے عطا کرے، اور زندگی میں اور موت کے بعد ہمیں تمام بھلائیوں کی آخری منزلوں تک پہنچائے۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर ऐसी रहमत नाज़िल कर जिसके ज़रिए तू हमें तमाम ख़ौफ़ और आफ़तों से नजात दे, हमारी सारी ज़रूरतें पूरी करे, हमें सब गुनाहों से पाक करे, अपने यहाँ हमें सबसे ऊँचे दर्जे दे, और ज़िंदगी में और मौत के बाद हमें हर भलाई की आख़िरी मंज़िल तक पहुँचाए।"),
'classic/nariya': dict(
 en="O Allah, send a perfect blessing and complete peace upon our master Muhammad, through whom knots are untied, distress is lifted, needs are fulfilled, hopes and good endings are attained, and rain is sought by his noble face — and upon his family and companions, in every glance and every breath, as many times as all that is known to You.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر کامل رحمت اور پوری سلامتی نازل فرما، جن کے وسیلے سے گرہیں کھلتی ہیں، مصیبتیں دور ہوتی ہیں، حاجتیں پوری ہوتی ہیں، مرادیں اور اچھا خاتمہ نصیب ہوتا ہے، اور جن کے مبارک چہرے کے وسیلے سے بادل سے بارش مانگی جاتی ہے؛ اور آپ کی آل اور اصحاب پر بھی، ہر لمحہ اور ہر سانس میں، ان تمام چیزوں کی تعداد کے برابر جو تیرے علم میں ہیں۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर कामिल रहमत और पूरी सलामती नाज़िल कर, जिनके वसीले से गिरहें खुलती हैं, मुसीबतें दूर होती हैं, ज़रूरतें पूरी होती हैं, मुरादें और अच्छा ख़ात्मा नसीब होता है, और जिनके मुबारक चेहरे के वसीले से बारिश माँगी जाती है; और आपकी आल और साथियों पर भी, हर पल और हर साँस में, उन तमाम चीज़ों की गिनती के बराबर जो तेरे इल्म में हैं।"),
'classic/fatih': dict(
 en="O Allah, send blessings upon our master Muhammad, the opener of what was closed, the seal of what came before, the one who makes the truth victorious by the truth, the guide to Your straight path — and upon his family, as befits his immense worth and rank.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر رحمت نازل فرما، جو بند کو کھولنے والے، پہلے آنے والوں کے خاتم، حق کے ذریعے حق کی مدد کرنے والے اور تیری سیدھی راہ کی طرف رہنمائی کرنے والے ہیں؛ اور آپ کی آل پر بھی، جیسا آپ کی عظیم قدر و منزلت کا حق ہے۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर रहमत नाज़िल कर, जो बंद को खोलने वाले, पहले आने वालों के ख़ातम, हक़ के ज़रिए हक़ की मदद करने वाले और तेरे सीधे रास्ते की तरफ़ रहनुमाई करने वाले हैं; और आपकी आल पर भी, जैसा आपकी अज़ीम क़द्र-ओ-मंज़िलत का हक़ है।"),
'classic/ghousia': dict(
 en="O Allah, send blessings upon our master Muhammad, whose light preceded creation and whose appearance is a mercy to the worlds — as many as those of Your creation who have passed and who remain, the fortunate and the wretched among them; a blessing that exceeds all counting and encompasses every limit, without end or cessation, lasting as long as You last — and upon his family and companions, and send peace likewise.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر رحمت نازل فرما، جن کا نور مخلوق سے پہلے ہے اور جن کا ظہور جہانوں کے لیے رحمت ہے؛ تیری مخلوق میں سے گزر جانے والوں اور باقی رہنے والوں، خوش نصیبوں اور بدنصیبوں کی تعداد کے برابر؛ ایسی رحمت جو ہر گنتی سے بڑھ جائے اور ہر حد کو گھیر لے، جس کی نہ انتہا ہو نہ اختتام، جو تیرے دوام کے ساتھ دائم رہے؛ اور آپ کی آل و اصحاب پر بھی، اور اسی طرح سلام بھیج۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर रहमत नाज़िल कर, जिनका नूर मख़लूक़ से पहले है और जिनका ज़ुहूर जहानों के लिए रहमत है; तेरी मख़लूक़ में से गुज़र जाने वालों और बाक़ी रहने वालों, ख़ुशनसीबों और बदनसीबों की गिनती के बराबर; ऐसी रहमत जो हर गिनती से बढ़ जाए और हर हद को घेर ले, जिसका न अंत हो न ख़ात्मा, जो तेरे हमेशा रहने के साथ हमेशा रहे; और आपकी आल और साथियों पर भी, और इसी तरह सलाम भेज।"),
'classic/mahi': dict(
 en="O Allah, send blessings upon Muhammad and the family of Muhammad, the best of creation, the most excellent of humankind and the intercessor for the nations on the Day of Gathering and Rising; bless our master Muhammad and his family by the number of all that You know; bless, honour and give peace to Muhammad and his family; bless all the prophets and messengers, all the angels brought near and the righteous servants of Allah, and send abundant peace — by Your mercy, bounty and generosity, O Most Generous of the generous, O Most Merciful of the merciful, O Eternal, O Everlasting, O Ever-Living, O Sustainer, O Single, O One, O Self-Sufficient, O He who neither begets nor is begotten and to whom none is equal.",
 ur="اے اللہ! محمد ﷺ اور آلِ محمد پر رحمت بھیج جو بہترین مخلوق، انسانوں میں افضل اور حشر و نشر کے دن امتوں کے شفیع ہیں؛ ہمارے آقا محمد اور ان کی آل پر ان تمام چیزوں کی تعداد میں رحمت بھیج جو تیرے علم میں ہیں؛ محمد اور آلِ محمد پر رحمت، برکت اور سلامتی بھیج؛ تمام انبیاء و مرسلین، تمام مقرب فرشتوں اور اللہ کے نیک بندوں پر رحمت بھیج، اور بہت بہت سلام بھیج — اپنی رحمت، فضل اور کرم سے، اے سب کریموں سے زیادہ کریم، اے سب رحم کرنے والوں سے زیادہ رحم کرنے والے، اے قدیم، اے دائم، اے حی، اے قیوم، اے وتر، اے احد، اے صمد، اے وہ جس نے نہ جنا نہ جنا گیا اور نہ کوئی اس کے برابر ہے۔",
 hi="ऐ अल्लाह! मुहम्मद ﷺ और आल-ए-मुहम्मद पर रहमत भेज जो बेहतरीन मख़लूक़, इंसानों में सबसे अफ़ज़ल और हश्र के दिन उम्मतों के शफ़ीअ हैं; हमारे आक़ा मुहम्मद और उनकी आल पर उन तमाम चीज़ों की गिनती में रहमत भेज जो तेरे इल्म में हैं; मुहम्मद और उनकी आल पर रहमत, बरकत और सलामती भेज; तमाम नबियों और रसूलों, तमाम मुक़र्रब फ़रिश्तों और अल्लाह के नेक बंदों पर रहमत भेज, और बहुत-बहुत सलाम भेज — अपनी रहमत, फ़ज़्ल और करम से, ऐ सबसे बड़े करीम, ऐ सबसे ज़्यादा रहम करने वाले, ऐ क़दीम, ऐ दाइम, ऐ हय्य, ऐ क़य्यूम, ऐ वित्र, ऐ अहद, ऐ समद, ऐ वह जिसने न जना न जना गया और कोई उसके बराबर नहीं।"),
'classic/razaviya': dict(
 en="May Allah send blessings upon the Unlettered Prophet and his family; may Allah bless him and grant him peace — blessings and peace be upon you, O Messenger of Allah.",
 ur="اللہ نبیِ امی ﷺ اور ان کی آل پر رحمت نازل فرمائے، اللہ ان پر رحمت اور سلام بھیجے؛ یا رسول اللہ! آپ پر درود و سلام ہو۔",
 hi="अल्लाह नबी-ए-उम्मी ﷺ और उनकी आल पर रहमत नाज़िल करे, अल्लाह उन पर रहमत और सलाम भेजे; या रसूलल्लाह! आप पर दुरूद-ओ-सलाम हो।"),
'more/taj': dict(
 en="O Allah, send blessings upon our master and patron Muhammad — owner of the crown, the Ascension, the Buraq and the banner; repeller of affliction, epidemic, famine, illness and pain; whose name is written, raised, accepted in intercession and inscribed on the Tablet and the Pen; master of Arabs and non-Arabs; whose blessed body is sanctified, fragrant, pure and radiant in the House and the Sanctuary; the morning sun, the full moon of the dark night, the head of the heights, the light of guidance, the refuge of creation, the lamp in the darkness, of beautiful character, intercessor of the nations, owner of generosity and kindness. Allah is his protector, Jibril his servant, the Buraq his mount, the Ascension his journey, the Lote Tree of the Furthest Boundary his station, 'two bows' length' his goal — and the goal is his aim, and the aim he attained. Master of the messengers, seal of the prophets, intercessor for sinners, companion of strangers, a mercy to the worlds, comfort of the lovers, desire of the yearning, sun of the knowers, lamp of the wayfarers, light of those brought near, lover of the poor, strangers and needy, master of jinn and mankind, prophet of the two Sanctuaries, imam of the two Qiblas, our means in both worlds, owner of 'two bows' length', beloved of the Lord of the two Easts and two Wests, grandfather of al-Hasan and al-Husayn, our patron and the patron of jinn and mankind, Abu al-Qasim Muhammad son of Abdullah, a light from the light of Allah. O you who yearn for the light of his beauty, send blessings upon him, his family and companions, and greet them with abundant peace.",
 ur="اے اللہ! ہمارے آقا و مولا محمد ﷺ پر رحمت نازل فرما — تاج، معراج، براق اور جھنڈے والے؛ بلا، وبا، قحط، بیماری اور درد کو دور کرنے والے؛ جن کا نام لوح و قلم میں لکھا ہوا، بلند، مقبولِ شفاعت اور نقش ہے؛ عرب و عجم کے سردار؛ جن کا جسمِ مبارک بیت اللہ اور حرم میں مقدس، معطر، پاک اور منور ہے؛ چاشت کے سورج، اندھیری رات کے چاند، بلندیوں کے صدر، ہدایت کے نور، مخلوق کی پناہ گاہ، تاریکیوں کے چراغ، عمدہ اخلاق والے، امتوں کے شفیع، سخاوت و کرم والے۔ اللہ ان کا نگہبان، جبریل ان کے خادم، براق ان کی سواری، معراج ان کا سفر، سدرۃ المنتہیٰ ان کا مقام، قابَ قوسین ان کا مطلوب — مطلوب ہی ان کا مقصود اور مقصود ان کو حاصل۔ رسولوں کے سردار، نبیوں کے خاتم، گنہگاروں کے شفیع، پردیسیوں کے غمخوار، جہانوں کے لیے رحمت، عاشقوں کی راحت، مشتاقوں کی مراد، عارفوں کے سورج، سالکوں کے چراغ، مقربوں کی روشنی، فقیروں، پردیسیوں اور مسکینوں سے محبت کرنے والے، جن و انس کے سردار، حرمین کے نبی، قبلتین کے امام، دونوں جہانوں میں ہمارا وسیلہ، قابَ قوسین والے، مشرقین و مغربین کے رب کے محبوب، حسن و حسین کے نانا، ہمارے اور جن و انس کے مولا، ابوالقاسم محمد بن عبداللہ، اللہ کے نور سے ایک نور۔ اے ان کے جمال کے نور کے مشتاقو! ان پر، ان کی آل اور اصحاب پر درود بھیجو اور خوب سلام بھیجو۔",
 hi="ऐ अल्लाह! हमारे आक़ा-ओ-मौला मुहम्मद ﷺ पर रहमत नाज़िल कर — ताज, मेराज, बुराक़ और झंडे वाले; बला, वबा, क़हत, बीमारी और दर्द को दूर करने वाले; जिनका नाम लौह-ओ-क़लम में लिखा, बुलंद, मक़बूल-ए-शफ़ाअत और नक़्श है; अरब-ओ-अजम के सरदार; जिनका मुबारक जिस्म बैतुल्लाह और हरम में मुक़द्दस, ख़ुशबूदार, पाक और रौशन है; चाश्त के सूरज, अँधेरी रात के चाँद, बुलंदियों के सदर, हिदायत के नूर, मख़लूक़ की पनाहगाह, अँधेरों के चिराग़, उम्दा अख़लाक़ वाले, उम्मतों के शफ़ीअ, सख़ावत-ओ-करम वाले। अल्लाह उनका निगहबान, जिब्रील उनके ख़ादिम, बुराक़ उनकी सवारी, मेराज उनका सफ़र, सिदरतुल मुंतहा उनका मक़ाम, क़ाबा क़ौसैन उनका मतलूब — मतलूब ही उनका मक़सूद और मक़सूद उन्हें हासिल। रसूलों के सरदार, नबियों के ख़ातम, गुनाहगारों के शफ़ीअ, परदेसियों के ग़मख़्वार, जहानों के लिए रहमत, आशिक़ों की राहत, मुश्ताक़ों की मुराद, आरिफ़ों के सूरज, सालिकों के चिराग़, मुक़र्रबों की रौशनी, फ़क़ीरों, परदेसियों और मिस्कीनों से मोहब्बत करने वाले, जिन्न-ओ-इंस के सरदार, हरमैन के नबी, क़िब्लतैन के इमाम, दोनों जहानों में हमारा वसीला, क़ाबा क़ौसैन वाले, मशरिक़ैन-ओ-मग़रिबैन के रब के महबूब, हसन-ओ-हुसैन के नाना, हमारे और जिन्न-ओ-इंस के मौला, अबुल क़ासिम मुहम्मद बिन अब्दुल्लाह, अल्लाह के नूर से एक नूर। ऐ उनके जमाल के नूर के मुश्ताक़ो! उन पर, उनकी आल और साथियों पर दुरूद भेजो और ख़ूब सलाम भेजो।"),
'more/shifa': dict(
 en="O Allah, send blessings upon our master Muhammad, the medicine of hearts and their cure, the wellbeing of bodies and their healing, the light of eyes and their brightness — and upon his family and companions, and grant them peace.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر رحمت نازل فرما، جو دلوں کی دوا اور ان کا علاج، جسموں کی عافیت اور ان کی شفا، آنکھوں کا نور اور ان کی روشنی ہیں؛ اور آپ کی آل و اصحاب پر بھی، اور سلام بھیج۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर रहमत नाज़िल कर, जो दिलों की दवा और उनका इलाज, जिस्मों की आफ़ियत और उनकी शिफ़ा, आँखों का नूर और उनकी रौशनी हैं; और आपकी आल और साथियों पर भी, और सलाम भेज।"),
'more/shifa2': dict(
 en="O Allah, send blessings, peace and grace upon the soul of our master Muhammad among the souls; send blessings and peace upon the heart of our master Muhammad among the hearts; upon the body of our master Muhammad among the bodies; and upon the resting place of our master Muhammad among the graves.",
 ur="اے اللہ! روحوں میں ہمارے آقا محمد ﷺ کی روح پر رحمت، سلامتی اور برکت نازل فرما؛ دلوں میں ہمارے آقا محمد کے دل پر رحمت و سلام؛ جسموں میں ہمارے آقا محمد کے جسم پر؛ اور قبروں میں ہمارے آقا محمد کی قبرِ انور پر رحمت و سلام نازل فرما۔",
 hi="ऐ अल्लाह! रूहों में हमारे आक़ा मुहम्मद ﷺ की रूह पर रहमत, सलामती और बरकत नाज़िल कर; दिलों में हमारे आक़ा मुहम्मद के दिल पर रहमत-ओ-सलाम; जिस्मों में हमारे आक़ा मुहम्मद के जिस्म पर; और क़ब्रों में हमारे आक़ा मुहम्मद की क़ब्र-ए-अनवर पर रहमत-ओ-सलाम नाज़िल कर।"),
'more/lakhi': dict(
 en="O Allah, send blessings and peace upon our master and patron Muhammad and the family of our master Muhammad — by the number of Allah's mercy, His bounty, His creation, His knowledge, His words, His generosity and the letters of His speech; by the number of raindrops, leaves on the trees, grains of desert sand, all that is created in the seas, seeds and fruits, nights and days, all that the night darkens and the day lights up, those who send blessings upon him and those who do not, the breaths of all creatures, the stars of the heavens, and everything in this world and the Hereafter. The blessings of Allah Most High, His angels, His prophets, His messengers and all creation be upon the master of the messengers, the imam of the God-fearing, the leader of those with radiant faces and limbs, the intercessor for sinners, our master and patron Muhammad, and upon his family, companions, wives, descendants, household and all who obey You among the people of the heavens and the earths — by Your mercy, O Most Merciful of the merciful, O Most Generous of the generous. And may Allah Most High bless our master Muhammad, his family and all his companions, and grant them peace, lasting, everlasting and abundant; and all praise belongs to Allah, Lord of the worlds.",
 ur="اے اللہ! ہمارے آقا و مولا محمد ﷺ اور ان کی آل پر رحمت و سلامتی بھیج — اللہ کی رحمت، فضل، مخلوق، علم، کلمات، کرم اور کلام کے حروف کی تعداد میں؛ بارش کے قطروں، درختوں کے پتوں، صحراؤں کی ریت، سمندروں کی مخلوق، دانوں اور پھلوں، رات اور دن، جس پر رات اندھیرا کرے اور دن روشنی، آپ پر درود پڑھنے والوں اور نہ پڑھنے والوں، تمام مخلوق کی سانسوں، آسمانوں کے ستاروں اور دنیا و آخرت کی ہر چیز کی تعداد میں۔ اللہ تعالیٰ، اس کے فرشتوں، انبیاء، رسولوں اور تمام مخلوق کی طرف سے رحمتیں ہوں رسولوں کے سردار، متقیوں کے امام، روشن چہرے اور اعضاء والوں کے قائد، گنہگاروں کے شفیع، ہمارے آقا و مولا محمد ﷺ پر، اور آپ کی آل، اصحاب، ازواج، اولاد، اہلِ بیت اور آسمانوں اور زمینوں میں تیرے تمام فرمانبرداروں پر، اپنی رحمت سے اے سب سے زیادہ رحم کرنے والے، اے سب سے زیادہ کرم کرنے والے۔ اور اللہ تعالیٰ ہمارے آقا محمد، ان کی آل اور تمام اصحاب پر رحمت اور ہمیشہ ہمیشہ بہت بہت سلام بھیجے، اور سب تعریف اللہ کے لیے ہے جو تمام جہانوں کا رب ہے۔",
 hi="ऐ अल्लाह! हमारे आक़ा-ओ-मौला मुहम्मद ﷺ और उनकी आल पर रहमत-ओ-सलामती भेज — अल्लाह की रहमत, फ़ज़्ल, मख़लूक़, इल्म, कलिमात, करम और कलाम के हुरूफ़ की गिनती में; बारिश की बूँदों, पेड़ों के पत्तों, रेगिस्तानों की रेत, समंदरों की मख़लूक़, दानों और फलों, रात और दिन, जिस पर रात अँधेरा करे और दिन रौशनी, आप पर दुरूद पढ़ने वालों और न पढ़ने वालों, सारी मख़लूक़ की साँसों, आसमानों के सितारों और दुनिया-ओ-आख़िरत की हर चीज़ की गिनती में। अल्लाह तआला, उसके फ़रिश्तों, नबियों, रसूलों और सारी मख़लूक़ की रहमतें हों रसूलों के सरदार, मुत्तक़ियों के इमाम, रौशन चेहरे वालों के क़ाइद, गुनाहगारों के शफ़ीअ, हमारे आक़ा-ओ-मौला मुहम्मद ﷺ पर, और आपकी आल, साथियों, बीवियों, औलाद, अहल-ए-बैत और आसमानों और ज़मीनों में तेरे तमाम फ़रमाँबरदारों पर, अपनी रहमत से ऐ सबसे ज़्यादा रहम करने वाले, ऐ सबसे ज़्यादा करम करने वाले। और अल्लाह तआला हमारे आक़ा मुहम्मद, उनकी आल और सब साथियों पर रहमत और हमेशा-हमेशा बहुत-बहुत सलाम भेजे, और सब तारीफ़ अल्लाह के लिए है जो सारे जहानों का रब है।"),
'more/akbar': dict(
 en="O Allah, send blessings and peace upon our master Muhammad, the unlettered Prophet, the Arab, of Quraysh, of Banu Hashim, of Makkah and Madinah; owner of the crown and the Ascension; owner of the expeditions and the gifts; owner of the Praised Station and the Pool to which people will come; owner of prostration to the Lord who is worshipped.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر رحمت و سلام بھیج، جو نبیِ امی، عربی، قریشی، ہاشمی، مکی، مدنی ہیں؛ تاج و معراج والے؛ لشکروں اور عطاؤں والے؛ مقامِ محمود اور حوضِ کوثر والے؛ معبود رب کے حضور سجدہ کرنے والے۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर रहमत-ओ-सलाम भेज, जो नबी-ए-उम्मी, अरबी, क़ुरैशी, हाशिमी, मक्की, मदनी हैं; ताज-ओ-मेराज वाले; लश्करों और अताओं वाले; मक़ाम-ए-महमूद और हौज़-ए-कौसर वाले; माबूद रब के हुज़ूर सजदा करने वाले।"),
'more/muqaddas': dict(
 en="O Allah, send blessings upon our master Muhammad until You are pleased, and send blessings upon our master Muhammad after You are pleased, and send blessings upon our master Muhammad for ever and ever.",
 ur="اے اللہ! ہمارے آقا محمد ﷺ پر اتنی رحمت بھیج کہ تو راضی ہو جائے، اور راضی ہونے کے بعد بھی ہمارے آقا محمد پر رحمت بھیج، اور ہمیشہ ہمیشہ ہمارے آقا محمد پر رحمت بھیجتا رہ۔",
 hi="ऐ अल्लाह! हमारे आक़ा मुहम्मद ﷺ पर इतनी रहमत भेज कि तू राज़ी हो जाए, और राज़ी होने के बाद भी हमारे आक़ा मुहम्मद पर रहमत भेज, और हमेशा-हमेशा हमारे आक़ा मुहम्मद पर रहमत भेजता रह।"),
'more/dalail': dict(
 en="May Allah bless our master and patron Muhammad, his family and companions, and grant them peace. O Allah, send blessings upon our master Muhammad, his wives and descendants, as You sent blessings upon our master Ibrahim; and bless our master Muhammad, his wives and descendants, as You blessed the family of our master Ibrahim; You are Praiseworthy, Glorious. O Allah, send blessings upon our master Muhammad and his family as You sent blessings upon our master Ibrahim, and bless our master Muhammad and the family of our master Muhammad as You blessed the family of our master Ibrahim among the worlds; You are Praiseworthy, Glorious. O Allah, send blessings upon our master Muhammad, the unlettered Prophet, and upon the family of our master Muhammad. O Allah, send blessings upon our master Muhammad, Your servant and Your messenger.",
 ur="اللہ ہمارے آقا و مولا محمد ﷺ، ان کی آل اور اصحاب پر رحمت و سلام بھیجے۔ اے اللہ! ہمارے آقا محمد، ان کی ازواج اور اولاد پر رحمت بھیج جیسے تو نے ہمارے آقا ابراہیم پر رحمت بھیجی، اور ہمارے آقا محمد، ان کی ازواج اور اولاد پر برکت بھیج جیسے تو نے آلِ ابراہیم پر برکت بھیجی، بیشک تو تعریف والا بزرگی والا ہے۔ اے اللہ! ہمارے آقا محمد اور ان کی آل پر رحمت بھیج جیسے تو نے ابراہیم پر رحمت بھیجی، اور محمد اور آلِ محمد پر برکت بھیج جیسے تو نے تمام جہانوں میں آلِ ابراہیم پر برکت بھیجی، بیشک تو تعریف والا بزرگی والا ہے۔ اے اللہ! ہمارے آقا محمد نبیِ امی اور آلِ محمد پر رحمت بھیج۔ اے اللہ! اپنے بندے اور رسول ہمارے آقا محمد پر رحمت بھیج۔",
 hi="अल्लाह हमारे आक़ा-ओ-मौला मुहम्मद ﷺ, उनकी आल और साथियों पर रहमत-ओ-सलाम भेजे। ऐ अल्लाह! हमारे आक़ा मुहम्मद, उनकी बीवियों और औलाद पर रहमत भेज जैसे तूने हमारे आक़ा इब्राहीम पर रहमत भेजी, और हमारे आक़ा मुहम्मद, उनकी बीवियों और औलाद पर बरकत भेज जैसे तूने आल-ए-इब्राहीम पर बरकत भेजी, बेशक तू तारीफ़ वाला बुज़ुर्गी वाला है। ऐ अल्लाह! हमारे आक़ा मुहम्मद और उनकी आल पर रहमत भेज जैसे तूने इब्राहीम पर रहमत भेजी, और मुहम्मद और आल-ए-मुहम्मद पर बरकत भेज जैसे तूने सारे जहानों में आल-ए-इब्राहीम पर बरकत भेजी, बेशक तू तारीफ़ वाला बुज़ुर्गी वाला है। ऐ अल्लाह! हमारे आक़ा मुहम्मद नबी-ए-उम्मी और आल-ए-मुहम्मद पर रहमत भेज। ऐ अल्लाह! अपने बंदे और रसूल हमारे आक़ा मुहम्मद पर रहमत भेज।"),
}
